```json
{
  "root_causes": [
    {
      "service": "product-catalog",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) AS spans, max(time) AS last_span FROM abnormal_traces WHERE service_name='product-catalog' GROUP BY service_name",
          "claim": "product-catalog emitted only 1 span in the abnormal window, last at 05:21:59.7, versus 277 GetProduct spans in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n, round(avg(duration/1e6),2) AS avg_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name LIKE '%ProductCatalog%' GROUP BY ALL",
          "claim": "checkout's GetProduct calls to product-catalog all return Error in about 0.1 ms, so the callee is unreachable and fails fast."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name, min(time) AS first_t, max(time) AS last_t, count(*) AS n, round(avg(value),0) AS avg_rss FROM abnormal_metrics WHERE service_name='product-catalog' AND metric='k8s.pod.memory.rss' GROUP BY 1",
          "claim": "product-catalog pod RSS collapses to about 0.35 MB with only 11 samples, versus about 15 MB over 24 normal samples."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "product-catalog",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='checkout' AND span_name LIKE '%ProductCatalog%' GROUP BY ALL",
          "claim": "Checkout's product-catalog GetProduct spans are all Error (19 of 19) once product-catalog is gone."
        }
      ]
    },
    {
      "from": "product-catalog",
      "to": "recommendation",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='recommendation' AND span_name LIKE '%ProductCatalog%' GROUP BY ALL",
          "claim": "Recommendation's ListProducts calls to product-catalog all return Error (29 of 29) in the abnormal window."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('POST /api/checkout','grpc.oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL",
          "claim": "Frontend's checkout calls and POST /api/checkout requests all fail with Error status (19 of 19 each)."
        }
      ]
    },
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('GET /api/recommendations','grpc.oteldemo.RecommendationService/ListRecommendations') GROUP BY ALL",
          "claim": "Frontend's /api/recommendations requests and recommendation gRPC calls all return Error (29 of 29 each)."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_status_code='Error' GROUP BY ALL",
          "claim": "Frontend-proxy ingress returns HTTP 500 errors (208 spans) for user requests that reach frontend failures."
        }
      ]
    }
  ]
}
